L26_1.m_Talk_VTN = L27_1
L27_1 = "\229\165\185\230\152\175\230\131\179\231\155\151\229\143\150\229\174\157\231\137\169\231\154\132\231\189\170\228\186\186\227\128\130\228\184\141\232\131\189\229\155\160\228\184\186\229\185\180\231\186\170\229\176\154\229\176\143\239\188\140\229\176\177\228\184\186\229\165\185\231\160\180\228\190\139\229\144\167\239\188\159"
